def fibonacci(n):
    """Return a list of the first n Fibonacci numbers."""
    if n <= 0:
        return []
    if n == 1:
        return [0]
    fib = [0, 1]
    while len(fib) < n:
        fib.append(fib[-1] + fib[-2])
    return fib

if __name__ == "__main__":
    import sys
    try:
        count = int(sys.argv[1]) if len(sys.argv) > 1 else 10
    except ValueError:
        print("Please provide a valid integer for the number of Fibonacci numbers.")
        sys.exit(1)
    print(fibonacci(count))

