def quicksort(arr):
    """Return a new list containing the sorted elements of arr using the quicksort algorithm."""
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quicksort(left) + middle + quicksort(right)

if __name__ == "__main__":
    sample = [3, 6, 8, 10, 1, 2, 1]
    print("Original list:", sample)
    print("Sorted list:", quicksort(sample))

